<script setup lang="ts">defineProps<{title:string;description?:string;price?:number;currency?:string;image?:string;modelValue?:boolean;disabled?:boolean}>();const emit=defineEmits<{'update:modelValue':[value:boolean]}>()</script><template><label class="vx-product-card" :class="{'is-selected':modelValue,'is-disabled':disabled}"><input type="checkbox" :checked="modelValue" :disabled="disabled" @change="emit('update:modelValue',($event.target as HTMLInputElement).checked)"/><img v-if="image" :src="image" :alt="title"/><span class="vx-product-card__copy"><strong>{{title}}</strong><small v-if="description">{{description}}</small></span><strong v-if="price!==undefined">{{new Intl.NumberFormat(undefined,{style:'currency',currency:currency||'USD'}).format(price)}}</strong></label></template>
